def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    remaining = {
        (r, c)
        for r in range(h) for c in range(w)
        if grid[r][c] != bg
    }
    components = []
    while remaining:
        start = remaining.pop()
        comp = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for p in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
                if p in remaining:
                    remaining.remove(p)
                    comp.add(p)
                    stack.append(p)
        components.append(comp)

    template = max(components, key=len)
    anchors = [p for comp in components if comp is not template for p in comp]

    r0 = min(r for r, c in template)
    r1 = max(r for r, c in template)
    c0 = min(c for r, c in template)
    c1 = max(c for r, c in template)
    cr, cc = (r0 + r1) // 2, (c0 + c1) // 2

    out = [row[:] for row in grid]
    for ar, ac in anchors:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                tr, tc = ar + r - cr, ac + c - cc
                if 0 <= tr < h and 0 <= tc < w:
                    out[tr][tc] = grid[r][c]
    return out
